/**
 * 计算接口代理前缀（H5 专用），按当前页面部署的子路径动态推导，避免写死部署目录。
 * 例：部署在 https://host/wechatapph5/ 时返回 '/wechatapph5/api'；
 *     部署在站点根 https://host/ 时返回 '/api'。
 * 取 pathname 的第一段作为部署目录，兼容 hash / history 路由（深层路径不会多拼一层）。
 * 非 H5（小程序等）返回空串，由调用方使用 getEnvBaseUrl() 拼接完整域名。
 */
export const getApiPrefix = (): string => {
  // #ifdef H5
  const pathname = window.location.pathname || '/'
  // 去掉末尾 index.html 后取第一段非空路径作为部署子目录（如 /wechatapph5），站点根则为空
  const firstSeg = pathname
    .replace(/\/index\.html$/, '')
    .split('/')
    .filter(Boolean)[0]
  const deployDir = firstSeg ? `/${firstSeg}` : ''
  return `${deployDir}/api`
  // #endif
  // #ifndef H5
  return ''
  // #endif
}

